const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]);
  const startDate = '2017-06-15';
  const endDate = '2017-06-21';

  // 2. Data Acquisition
  const modisLST = ee.ImageCollection('MODIS/11A1.061')
    .filterDate(startDate, endDate)
    .filterBounds(phoenix);

  const imageCount = modisLST.size().getInfo();
  if (imageCount === 0) {
    console.log('Evidence: No MODIS images found for the specified date and location.');
    console.log('A');
    return;
  }
  console.log(`Evidence: Found ${imageCount} MODIS images for the period.`);

  // 3. Processing: Mask poor quality pixels and convert units
  const toFahrenheit = function(image) {
    // Bits 0-1: Mandatory QA flags. 00 = Good quality.
    const quality = image.select('QC_Day');
    const goodQuality = quality.bitwiseAnd(0b11).eq(0);

    const lst = image.select('LST_Day_1km').updateMask(goodQuality);

    // Apply scale factor, convert Kelvin to Fahrenheit
    const tempF = lst.multiply(0.02)
      .subtract(273.15)
      .multiply(9.0/5.0)
      .add(32.0)
      .rename('Temperature_F');
    return tempF;
  };

  const tempFCollection = modisLST.map(toFahrenheit);

  // 4. Calculation: Find the maximum temperature over the time period
  const maxTempImage = tempFCollection.max();

  const tempStats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.max().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
    geometry: phoenix,
    scale: 1000,
    crs: 'EPSG:4326',
    maxPixels: 1e9
  });

  const maxTemp = tempStats.get('Temperature_F_max').getInfo();
  const pixelCount = tempStats.get('Temperature_F_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log('Evidence: No valid (good quality) pixels found over Phoenix.');
    console.log('C2');
    return;
  }

  if (maxTemp === null || typeof maxTemp === 'undefined') {
    console.log('Evidence: Calculation failed, could not retrieve a valid temperature value.');
    console.log('C3');
    return;
  }

  console.log(`Evidence: Peak temperature recorded: ${maxTemp.toFixed(2)} °F`);
  console.log(`Evidence: Number of valid pixels in analysis: ${pixelCount}`);

  if (maxTemp >= 110) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('D');
});
